const specialists = [];
for (const name of ["researcher", "analyst", "reviewer"]) {
  const agent = await client.beta.agents.create({
    name,
    model: "claude-sonnet-5-5",
    system: "Work as the " + name + " specialist.",
    tools: [{ type: "agent_toolset_20260401" }]
  });
  specialists.push({
    type: "agent" as const,
    id: agent.id, version: agent.version
  });
}
const coordinator = await client.beta.agents.create({
  name: "Research coordinator",
  model: "claude-opus-5-5",
  system: "Delegate by role and reconcile the reports.",
  tools: [{ type: "agent_toolset_20260401" }],
  multiagent: {
    type: "multiagent_20261001",
    subagents: {
      type: "enabled",
      inline_agents: { type: "disabled" },
      predefined_agents: specialists
    },
    workflows: { type: "disabled" },
    advisor: { type: "disabled" }
  }
});
